import React, { Component } from "react";
import Loader from "react-loader-spinner";
import { connect } from "react-redux";
import { Card, CardBody, CardHeader, Col, ListGroup, ListGroupItem, Row, TabContent, TabPane } from "reactstrap";

import { fetchAffiliates, fetchAffiliatesPaginated } from "../../actions/affiliates";
import {
	addAffilaiteToUser,
	addAffiliatesToUsers,
	fetchUserAffiliates,
	fetchUsers,
	removeAffilaiteFromUser,
} from "../../actions/utils";
import { hasRole } from "../../Utils/Auth";

class UserManagement extends Component {
	constructor (props) {
		super(props);
		this.state = {
			activeTab3             : "",
			selectedEmail          : "",
			allAffiliates          : [],
			selectedUserAffiliates : [],
		};
		this.handleCheckboxClick = this.handleCheckboxClick.bind(this);
	}

	static getDerivedStateFromProps (props, state) {
		if (props.utils) {
			if (props.utils.userAffiliates !== state.selectedUserAffiliates) {
				return {
					selectedUserAffiliates : props.utils.userAffiliates,
				};
			}
		}

		// Return null if the state hasn't changed
		return null;
	}

	componentDidMount () {
		this.props.fetchUsers();
		this.props.fetchAffiliates();
	}

	componentDidUpdate (prevProps) {
		console.log("ALL AFFILIATES", this.props);
		if (prevProps.utils.users !== this.props.utils.users) {
			const { users } = this.props.utils;
			if (users) {
				if (users.payload.length !== 0) {
					// calls the necessary users Action Creators only if there are users.
					// Checkes if there is a user Affiliate has been set before
					if (localStorage.getItem("currentSelectedUserEmail")) {
						this.props.fetchUserAffiliates(localStorage.getItem("currentSelectedUserEmail")); // get affiliates for that user
						this.setState({
							activeTab3    : localStorage.getItem("currentSelectedUserEmail"),
							selectedEmail : localStorage.getItem("currentSelectedUserEmail"),
						});
					}
				}
			}
		}

		if (prevProps.affiliates.affiliateListUnPaginated !== this.props.affiliates.affiliateListUnPaginated) {
			this.setState({
				allAffiliates : this.props.affiliates.affiliateListUnPaginated,
			});
		}
	}

	toggle3 = (tab, email) => {
		this.props.fetchUserAffiliates(email);
		if (this.state.activeTab3 !== tab) {
			this.setState({
				activeTab3    : tab,
				selectedEmail : email,
			});
		}
	};

	handleCheckboxClick (e) {
		const { value, checked } = e.target;
		const { utils, addAffilaiteToUser, removeAffilaiteFromUser } = this.props;
		const { selectedEmail } = this.state;
		// Value to post
		let values = {};

		if (checked) {
			values.affiliateCode = value;
			if (selectedEmail) {
				values.login = selectedEmail;
			} else {
				utils.users.payload.length ? (values.login = utils.users.payload[0].email) : (values.login = "");
			}

			if (values.login) {
				addAffilaiteToUser(values);
			}
		} else {
			!selectedEmail ? (values.login = utils.users.payload[0].email) : (values.login = selectedEmail);
			values.affiliateCode = value;
			removeAffilaiteFromUser(values);
		}
	}

	noUser = () => {
		localStorage.setItem("currentSelectedUserEmail", "");
		return <p className='capitalize text-center text-danger'>No user added yet!</p>;
	};

	render () {
		const { allAffiliates, selectedUserAffiliates } = this.state;
		let loggedInUser = JSON.parse(localStorage.getItem("decodedToken"));

		return (
			<div className='animated fadeIn'>
				<Row>
					<Col>
						{hasRole(loggedInUser, [ "ROLE_ADMIN" ]) ? (
							<Card>
								<CardHeader>
									<i className='fa fa-users' />
									<strong>User Management</strong>
								</CardHeader>
								<CardBody>
									<Row>
										<Col xs='4'>
											<ListGroup id='list-tab' role='tablist'>
												<h6 className='text-center'>Application Users</h6>
												{!this.props.utils.users && (
													<Row>
														<article className='mx-auto'>
															<Loader
																type='ThreeDots'
																color='#00BFFF'
																height={100}
																width={100}
															/>
														</article>
													</Row>
												)}
												{this.props.utils.users &&
													this.props.utils.users.payload.length === 0 &&
													this.noUser()}
												{this.props.utils.users ? (
													[ ...this.props.utils.users.payload ].map((item, index) => {
														//  Added to make the
														this.state.activeTab3 === item.staff.email &&
															localStorage.setItem(
																"currentSelectedUserEmail",
																item.staff.email,
															);

														return (
															<ListGroupItem
																style={{ cursor: "pointer" }}
																key={index}
																onClick={() =>
																	this.toggle3(item.staff.email, item.staff.email)}
																action
																active={this.state.activeTab3 === item.staff.email}
															>
																{item.staff.email}
															</ListGroupItem>
														);
													})
												) : null}
											</ListGroup>
										</Col>

										<Col xs='8'>
											<h6 className='text-center'>Ecobank Affiliates</h6>
											<TabContent>
												<TabPane>
													{!this.props.affiliates.affiliateListUnPaginated && (
														<Row>
															<article className='mx-auto'>
																<Loader
																	type='ThreeDots'
																	color='#00BFFF'
																	height={100}
																	width={100}
																/>
															</article>
														</Row>
													)}
													{allAffiliates ? (
														allAffiliates.map((item, index) => (
															<div key={index}>
																<label>
																	<input
																		type='checkbox'
																		value={item.code}
																		checked={
																			selectedUserAffiliates ? (
																				selectedUserAffiliates.some(
																					(affiliate) =>
																						affiliate.name === item.name,
																				)
																			) : (
																				false
																			)
																		}
																		onChange={this.handleCheckboxClick}
																	/>{" "}
																	&nbsp;{item.code} {item.name}
																</label>
															</div>
														))
													) : (
														<div>
															{this.props.affiliates.affiliateListError && (
																<p className='capitalize text-center text-danger'>
																	Could not load affilates try again!.
																</p>
															)}

															{!this.props.affiliates.affiliateListError && (
																<p className='capitalize text-center text-danger'>
																	No affilates added yet!
																</p>
															)}
														</div>
													)}
												</TabPane>
											</TabContent>
										</Col>
									</Row>
								</CardBody>
							</Card>
						) : null}
					</Col>
				</Row>
			</div>
		);
	}
}

const mapStateToProps = (state) => {
	return {
		sres       : state.sres,
		utils      : state.utils,
		affiliates : state.affiliates,
	};
};

export default connect(mapStateToProps, {
	fetchUsers,
	fetchAffiliatesPaginated,
	addAffiliatesToUsers,
	addAffilaiteToUser,
	removeAffilaiteFromUser,
	fetchUserAffiliates,
	fetchAffiliates,
})(UserManagement);
